$$\begin{array}{l}
  {ay_{2}^{''} + by_{2}^{\prime} + cy_{2} = a{({2re^{ rx} + r^{2}xe^{ rx}})} + b\left( {e^{ rx} + rxe^{ rx}} \right) + cxe^{ rx}} \\
  {\phantom{ay_{2}^{''} + by_{2}^{\prime} + cy_{2}} = \left( {2ar + b} \right)e^{ rx} + {({ar^{2} + br + c})}xe^{ rx}} \\
  {\phantom{ay_{2}^{''} + by_{2}^{\prime} + cy_{2}} = 0\left( e^{ rx} \right) + 0\left( {xe^{ rx}} \right) = 0}
  \end{array}$$

$$\begin{array}{l}
  {y = C_{1}e^{r_{1}x} + C_{2}e^{r_{2}x} = C_{1}e^{({\alpha + i\beta})x} + C_{2}e^{({\alpha - i\beta})x}} \\
  {\phantom{y} = C_{1}e^{\alpha x}\left( {\cos\beta x + i\sin\beta x} \right) + C_{2}e^{\alpha x}\left( {\cos\beta x - i\sin\beta x} \right)} \\
  {\phantom{y} = e^{\alpha x}\left\lbrack {\left( {C_{1} + C_{2}} \right)\cos\beta x + i\left( {C_{1} - C_{2}} \right)\sin\beta x} \right\rbrack} \\
  {\phantom{y} = e^{\alpha x}\left( {c_{1}\cos\beta x - c_{2}\sin\beta x} \right)}
  \end{array}$$
